const items = $input.all().map(item => item.json);
return [{
  json: {
    success: true,
    clientId: $('Webhook Consulta Historial').first().json.body.clientId,
    totalSesiones: items.length,
    historial: items,
    resumenTexto: items.length === 0 
      ? 'Aún no registras sesiones previas de tratamientos.' 
      : `Cuentas con ${items.length} sesión(es) registrada(s). Tu último tratamiento fue ${items[0].treatment_name} el ${items[0].date}.`
  }
}];
